// Some portions generated by Codex
import assert from "node:assert/strict";
import test from "node:test";
import { graphNodePresentation } from "../../../main/frontend/graph-explorer/graph-geometry.ts";
import { graphSvg, graphTurtle } from "../../../main/frontend/graph-explorer/graph-export.ts";
import { layoutDimensionsChanged } from "../../../main/frontend/graph-explorer/graph-model.ts";
import { largeGraphTooltip } from "../../../main/frontend/graph-explorer/large-graph-tooltip.ts";
import * as collectionPresentation from "../../../main/frontend/graph-explorer/collection-presentation.ts";
import { GraphScene } from "../../../main/frontend/graph-explorer/graph-scene.ts";

function collectionNode(labels = ["Alice", "Bob", "Alice"], count = labels.length) {
  return {
    id: "urn:list", label: "urn:list", kind: "iri", x: 100, y: 100,
    collection: {
      headId: "urn:list", status: "complete", count, loadedCount: count,
      preview: labels.map((label, index) => ({
        position: index + 1, cellId: `urn:cell:${index}`, memberId: `urn:member:${label}`,
        label, kind: "literal",
      })),
      hiddenCount: count - labels.length,
    },
  };
}

function exportSvg(nodes, edges = []) {
  return graphSvg({
    nodes, edges, curves: new Map(), labels: new Map(), color: (value) => value,
    palette: { background: "#fff", edge: "#999", nodeText: "#111", labelText: "#333", labelFill: "#eee", font: "sans-serif" },
  });
}

test("collection cards reserve bounded space for ordered preview rows", () => {
  const node = collectionNode();
  const presentation = graphNodePresentation(node);
  const ordinary = graphNodePresentation({ ...node, collection: undefined });
  assert.ok(presentation.height > ordinary.height, "collection rows need their own height");
  assert.equal(presentation.label, "List · 3 items");
  const long = graphNodePresentation(collectionNode(["A", "B", "C", "D"], 50_000));
  assert.ok(long.height < 300, "total length must not determine canvas card height");
  assert.equal(long.height, graphNodePresentation(collectionNode(["A", "B", "C", "D"], 5)).height);
  assert.ok(long.height > presentation.height, "remaining members need a visible footer");
});

test("collection preview changes invalidate dimensions even when head label and kind stay the same", () => {
  const before = collectionNode(["A"]);
  const after = collectionNode(["A", "B", "C"]);
  assert.equal(before.label, after.label);
  assert.equal(layoutDimensionsChanged([before], [after]), true);
  assert.equal(layoutDimensionsChanged([before], [{ ...before, x: 200 }]), false);
});

test("SVG export preserves numbered occurrences and escapes member text", () => {
  const svg = exportSvg([collectionNode(["A & <B>", "other", "A & <B>"])]);
  assert.match(svg, /List · 3 items/);
  assert.equal((svg.match(/A &amp; &lt;B&gt;/g) ?? []).length, 2, "duplicate occurrences remain separate rows");
  assert.match(svg, />1<\/text>[\s\S]*>2<\/text>[\s\S]*>3<\/text>/);
  assert.doesNotMatch(svg, /A & <B>/);
});

test("SVG collection membership connections are visibly distinct from asserted predicates", () => {
  const source = collectionNode(["Alice"]);
  const target = { id: "urn:alice", label: "Alice", kind: "iri", x: 400, y: 100 };
  const edge = {
    id: "member:1", source: source.id, target: target.id, predicate: "urn:display:member", label: "1",
    collection: { headId: source.id, positions: [1], cellIds: ["urn:cell:0"] },
  };
  const svg = exportSvg([source, target], [edge]);
  const path = svg.split("\n").find((line) => line.startsWith("<path d=\"M"));
  assert.ok(path, "the membership connector is drawn");
  assert.match(path, /stroke-dasharray=/);
  assert.doesNotMatch(path, /marker-end=/, "membership summaries are not asserted RDF arrows");
});

test("SVG export uses the row port when no routed curve is supplied and Turtle keeps the member", () => {
  const card = collectionNode(["First", "Book"]);
  const author = { id: "urn:author", label: "Author", kind: "iri", x: 550, y: 130 };
  const row = { headId: card.id, memberId: "urn:member:Book", position: 2 };
  const writtenBy = { id: "writtenBy", source: card.id, target: author.id, sourceRow: row, predicate: "urn:writtenBy", label: "written by" };
  const reviews = { id: "reviews", source: author.id, target: card.id, targetRow: row, predicate: "urn:reviews", label: "reviews" };
  const svg = exportSvg([card, author], [writtenBy, reviews]);
  const { width, height, collection } = graphNodePresentation(card);
  const x = card.x + width / 2;
  const y = card.y - height / 2 + collection.rows[1].y + collectionPresentation.COLLECTION_ROW_HEIGHT / 2;
  assert.equal((svg.match(/r="3\.2"/g) ?? []).length, 1, "both arrows share one socket");
  assert.ok(svg.includes(`<circle cx="${x}" cy="${y}" r="3.2"`));
  assert.ok(svg.includes(`<path d="M ${x} ${y} `), "the outbound path starts at the socket");
  assert.ok(svg.includes(`L ${x} ${y}" fill="none"`), "the inbound path ends at the socket");
  const turtle = graphTurtle({ nodes: [card, author], edges: [writtenBy, reviews] });
  assert.match(turtle, /<urn:member:Book> <urn:writtenBy> <urn:author>/);
  assert.match(turtle, /<urn:author> <urn:reviews> <urn:member:Book>/);
});

test("large graph hover identifies the collection while keeping its original head identity", () => {
  const tooltip = largeGraphTooltip(collectionNode());
  assert.match(tooltip.title, /List · 3 items/);
  assert.match(tooltip.detail, /urn:list/);
});

test("Turtle never serializes collection membership summaries as asserted relationships", () => {
  const graph = {
    nodes: [], revision: 1,
    edges: [
      { id: "real", source: "urn:owner", predicate: "urn:members", target: "urn:list", label: "members" },
      { id: "display", source: "urn:list", predicate: "urn:display:member", target: "urn:alice", label: "1",
        collection: { headId: "urn:list", positions: [1], cellIds: ["urn:cell:0"] } },
    ],
  };
  const turtle = graphTurtle(graph);
  assert.match(turtle, /<urn:owner> <urn:members> <urn:list>/);
  assert.doesNotMatch(turtle, /urn:display:member|urn:alice/);
});

test("collection member windows reach a long list's last occurrence with bounded rows", () => {
  const range = collectionPresentation.collectionMemberWindow(50_000, 49_995 * 52);
  assert.equal(range.end, 50_000);
  assert.ok(range.end - range.start <= 11);
  assert.deepEqual(collectionPresentation.collectionMemberWindow(0, 0), { start: 0, end: 0 });
  assert.equal(collectionPresentation.collectionMemberWindow(3, 100_000).end, 3);
});

test("large graph keeps membership topology but separates it from solid RDF edges", () => {
  const head = collectionNode(["Alice"]);
  const member = { id: "urn:alice", label: "Alice", kind: "iri" };
  const graph = { nodes: [head, member], edges: [
    { id: "rdf", source: head.id, target: member.id, predicate: "urn:related", label: "related" },
    { id: "display", source: head.id, target: member.id, predicate: "urn:display:member", label: "1",
      collection: { headId: head.id, positions: [1], cellIds: ["urn:cell:0"] } },
  ], revision: 1 };
  const scene = new GraphScene(graph);
  assert.deepEqual([...scene.solidEdges], [0, 1]);
  assert.deepEqual([...scene.collectionEdges], [1]);
  assert.deepEqual([...scene.neighbors(0)], [1]);
  assert.equal(scene.edges.length, 4);
  const ordinary = new GraphScene({ ...graph, edges: [graph.edges[0]] });
  assert.equal(ordinary.solidEdges, ordinary.edges, "ordinary graphs reuse their edge buffer");
});

test("inspector presentation controls act only on maximal heads and the empty list", () => {
  const info = { status: "complete", count: 2, loadedCount: 2, collapsible: true };
  const analysis = { heads: new Set(["head", "ambiguous"]), collections: new Map([
    ["head", { ...info, headId: "head" }],
    ["tail", { ...info, headId: "tail", count: 1, loadedCount: 1 }],
    ["nil", { ...info, headId: "nil", count: 0, loadedCount: 0 }],
    ["ambiguous", { ...info, headId: "ambiguous", status: "ambiguous", collapsible: false }],
  ]), cells: new Map() };
  assert.equal(collectionPresentation.canToggleCollectionView(analysis, "head"), true);
  assert.equal(collectionPresentation.canToggleCollectionView(analysis, "tail"), false);
  assert.equal(collectionPresentation.canToggleCollectionView(analysis, "nil"), true);
  assert.equal(collectionPresentation.canToggleCollectionView(analysis, "ambiguous"), false);
});
